#include "openfs/fsck.h"
#include "openfs/bitmap.h"
#include "openfs/extent.h"
#include <limits.h>
#include <stdlib.h>
static openfs_fsck_result_t icount(const openfs_superblock_t*s,uint64_t*n){if(s==NULL||s->block_size==0U||s->inode_table_blocks>UINT64_MAX/s->block_size)return OPENFS_FSCK_CORRUPT;*n=(s->inode_table_blocks*s->block_size)/OPENFS_INODE_SIZE;return *n?OPENFS_FSCK_OK:OPENFS_FSCK_CORRUPT;}
static int add(uint64_t a,uint64_t b,uint64_t*o){if(b>UINT64_MAX-a)return 0;*o=a+b;return 1;}
openfs_fsck_result_t openfs_fsck(openfs_block_device_t*d,const openfs_superblock_t*s,uint64_t*errors){if(errors)*errors=0U;if(!openfs_block_device_is_valid(d)||s==NULL||errors==NULL)return OPENFS_FSCK_INVALID_ARGUMENT;if(openfs_validate_superblock(d,s)!=OPENFS_FORMAT_OK)return OPENFS_FSCK_CORRUPT;uint64_t count=0U;if(icount(s,&count)!=OPENFS_FSCK_OK)return OPENFS_FSCK_CORRUPT;uint64_t bad=0U;for(uint64_t n=1U;n<=count;n++){int used=0;if(openfs_bitmap_test(d,s->inode_bitmap_start,s->inode_bitmap_blocks,n-1U,&used)!=OPENFS_BITMAP_OK)return OPENFS_FSCK_IO_ERROR;openfs_inode_t in;if(openfs_inode_read(d,s->inode_table_start,n,count,&in)!=OPENFS_INODE_OK){if(used)bad++;continue;}if(used){if(in.mode==OPENFS_INODE_MODE_FREE||in.link_count==0U||in.inode_number!=n)bad++;if(in.mode==OPENFS_INODE_MODE_FREE&&in.blocks!=0U)bad++;for(uint32_t i=0U;i<in.extent_count;i++){openfs_extent_t e;if(openfs_inode_get_extent(&in,i,&e)!=OPENFS_EXTENT_OK||e.block_count==0U) {bad++;continue;}uint64_t pe=0U;uint64_t data_end=0U;if(!add(s->data_start,s->data_blocks,&data_end)||!add(e.physical_start,e.block_count,&pe)||e.physical_start<s->data_start||pe>data_end)bad++;else{for(uint64_t b=0U;b<e.block_count;b++){int allocated=0;if(openfs_bitmap_test(d,s->block_bitmap_start,s->block_bitmap_blocks,e.physical_start+b,&allocated)!=OPENFS_BITMAP_OK)return OPENFS_FSCK_IO_ERROR;if(!allocated)bad++;}}if(i>0U){openfs_extent_t prev;uint64_t le=0U;if(openfs_inode_get_extent(&in,i-1U,&prev)!=OPENFS_EXTENT_OK||!add(prev.logical_start,prev.block_count,&le)||e.logical_start<le)bad++;}}}else if(in.mode!=OPENFS_INODE_MODE_FREE||in.link_count!=0U){bad++;}}*errors=bad;return bad==0U?OPENFS_FSCK_OK:OPENFS_FSCK_CORRUPT;}